import re

TIME = r"(\d{1,2})(?::(\d{2}))? (AM|PM)"


def convert(s):
    match = re.fullmatch(TIME + " to " + TIME, s)
    if not match:
        raise ValueError("неправильный формат")
    parts = match.groups()
    return f"{to_24(*parts[:3])} to {to_24(*parts[3:])}"


def to_24(hour, minute, meridiem):
    hour, minute = int(hour), int(minute or 0)
    if not 1 <= hour <= 12 or minute > 59:
        raise ValueError("неправильное время")
    if meridiem == "AM":
        hour = 0 if hour == 12 else hour
    else:
        hour = 12 if hour == 12 else hour + 12
    return f"{hour:02}:{minute:02}"

